"use client";
import { useEffect, useRef, useState } from "react";
import { api } from "./api";
import { Button, cx, inputClass } from "./ui";

type Ticket = { url: string; reference: string; when: string; party_size: number; name: string };
type Msg = { role: "user" | "assistant"; content: string; ticket?: Ticket; degraded?: boolean };
type Reply = { token: string; reply: string; ticket?: Ticket; escalated: boolean; degraded: boolean };

const URL_RE = /(https?:\/\/[^\s]+)/g;

function Text({ text }: { text: string }) {
  // Links are rendered as real anchors; everything else is plain text (React escapes it).
  return (
    <>
      {text.split(URL_RE).map((part, i) =>
        /^https?:\/\//.test(part)
          ? <a key={i} href={part} className="break-all font-semibold underline">{part.includes("/t/") ? "Open your ticket" : part}</a>
          : <span key={i}>{part}</span>)}
    </>
  );
}

export function BookingChat({ slug, agentName, greeting, suggestions, onDegraded }: { slug: string; agentName: string; greeting: string; suggestions: string[]; onDegraded: () => void }) {
  const storageKey = `abc-chat-${slug}`;
  const [messages, setMessages] = useState<Msg[]>([]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const token = useRef<string | null>(null);
  const end = useRef<HTMLDivElement>(null);
  const box = useRef<HTMLInputElement>(null);

  // Bring back this visitor's own conversation after a reload (same browser tab only).
  useEffect(() => {
    let saved: string | null = null;
    try { saved = sessionStorage.getItem(storageKey); } catch {}
    if (!saved) return;
    token.current = saved;
    api<{ messages: Msg[] }>(`/api/public/${slug}/chat`, { headers: { "x-conversation-token": saved } })
      .then((r) => setMessages(r.messages))
      .catch(() => {});
  }, [slug, storageKey]);

  useEffect(() => { end.current?.scrollIntoView({ block: "nearest", behavior: "smooth" }); }, [messages, busy]);

  async function send(text: string) {
    const message = text.trim();
    if (!message || busy) return;
    setInput(""); setError(""); setBusy(true);
    setMessages((m) => [...m, { role: "user", content: message }]);
    try {
      const r = await api<Reply>(`/api/public/${slug}/chat`, { body: { message, token: token.current } });
      if (r.token) { token.current = r.token; try { sessionStorage.setItem(storageKey, r.token); } catch {} }
      setMessages((m) => [...m, { role: "assistant", content: r.reply, ticket: r.ticket, degraded: r.degraded }]);
      if (r.degraded) onDegraded();
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(false);
      box.current?.focus();
    }
  }

  return (
    <div className="flex h-full min-h-[26rem] flex-col">
      <div className="flex-1 space-y-3 overflow-y-auto px-4 py-4" aria-live="polite" aria-label={`Conversation with ${agentName}`}>
        <Bubble role="assistant"><Text text={greeting} /></Bubble>
        {messages.length === 0 && (
          <div className="flex flex-wrap gap-2 pl-1">
            {suggestions.map((s) => (
              <button key={s} type="button" onClick={() => send(s)} className="rounded-full bg-white px-3.5 py-2 text-[15px] font-medium text-brand-deep ring-1 ring-line hover:ring-brand">{s}</button>
            ))}
          </div>
        )}
        {messages.map((m, i) => (
          <div key={i} className="space-y-2">
            <Bubble role={m.role}><Text text={m.content} /></Bubble>
            {m.ticket && (
              <a href={m.ticket.url} data-testid="chat-ticket" className="pop ml-1 block max-w-[20rem] rounded-2xl bg-ink p-4 text-white no-underline">
                <span className="block text-[13px] text-white/70">Reservation {m.ticket.reference}</span>
                <span className="mt-0.5 block font-display text-lg font-bold leading-tight">{m.ticket.when}</span>
                <span className="block text-[15px] text-white/85">{m.ticket.party_size} {m.ticket.party_size === 1 ? "guest" : "guests"}, {m.ticket.name}</span>
                <span className="mt-3 inline-flex min-h-10 items-center rounded-xl bg-mint px-4 font-semibold">Open your ticket</span>
              </a>
            )}
          </div>
        ))}
        {busy && <Bubble role="assistant"><span className="text-muted">{agentName} is typing…</span></Bubble>}
        {error && <p role="alert" className="rounded-xl bg-rose-soft px-3 py-2 text-[15px] text-rose">{error}</p>}
        <div ref={end} />
      </div>
      <form onSubmit={(e) => { e.preventDefault(); void send(input); }} className="flex gap-2 border-t border-line p-3">
        <input ref={box} value={input} onChange={(e) => setInput(e.target.value)} maxLength={1000} placeholder="Type your message" aria-label="Your message" className={inputClass} autoComplete="off" />
        <Button type="submit" disabled={busy || !input.trim()}>Send</Button>
      </form>
    </div>
  );
}

function Bubble({ role, children }: { role: "user" | "assistant"; children: React.ReactNode }) {
  return (
    <div className={cx("flex", role === "user" && "justify-end")}>
      <div className={cx("max-w-[85%] rounded-2xl px-4 py-2.5 text-[15.5px] leading-relaxed whitespace-pre-wrap", role === "user" ? "rounded-br-md bg-brand text-white" : "rounded-bl-md bg-white ring-1 ring-line")}>
        {children}
      </div>
    </div>
  );
}
