"use client";
import { useRef, useState } from "react";
import { api, ApiError, newKey } from "./api";
import { SlotPicker, type PickedSlot } from "./SlotPicker";
import { Button, Field, inputClass, Notice } from "./ui";

type Props = { slug: string; today: string; maxDate: string; maxParty: number; partyWord: string; services: { id: string; name: string }[] };
type Alt = { date: string; time: string; start: string };

const fmtDay = (iso: string) => new Date(`${iso}T12:00:00Z`).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", timeZone: "UTC" });

export function BookingForm({ slug, today, maxDate, maxParty, partyWord, services }: Props) {
  const [party, setParty] = useState(Math.min(2, maxParty));
  const [date, setDate] = useState(today);
  const [service, setService] = useState(services[0]?.id ?? "");
  const [slot, setSlot] = useState<PickedSlot | null>(null);
  const [who, setWho] = useState({ name: "", email: "", phone: "", notes: "", consent: true, website: "" });
  const [review, setReview] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [alts, setAlts] = useState<Alt[]>([]);
  const key = useRef(newKey()); // one key per booking attempt: a double click cannot book twice

  function toReview(e: React.FormEvent) {
    e.preventDefault();
    setError("");
    if (!slot) return setError("Choose a time first.");
    if (!who.email.trim() && !who.phone.trim()) return setError("Enter an email address or a phone number so we can reach you.");
    setReview(true);
  }

  async function confirm() {
    if (!slot) return;
    setBusy(true); setError(""); setAlts([]);
    try {
      const r = await api<{ ticketUrl: string }>(`/api/public/${slug}/reservations`, {
        body: { serviceId: service || null, startsAt: slot.start, partySize: party, notes: who.notes, idempotencyKey: key.current, website: who.website,
                customer: { name: who.name, email: who.email || null, phone: who.phone || null, consent: who.consent } },
      });
      window.location.assign(r.ticketUrl);
    } catch (e) {
      const err = e as ApiError;
      setError(err.message);
      if (err.code === "slot_unavailable") { setAlts((err.data?.alternatives as Alt[]) ?? []); setSlot(null); key.current = newKey(); }
      setReview(false); setBusy(false);
    }
  }

  if (review && slot) {
    return (
      <div className="space-y-4 p-5">
        <h3 className="text-xl font-bold">Check your reservation</h3>
        <dl className="divide-y divide-line rounded-xl ring-1 ring-line">
          {[["When", `${fmtDay(date)} at ${slot.time}`], [partyWord, String(party)], ["Name", who.name], ["Contact", [who.email, who.phone].filter(Boolean).join(", ")], ...(who.notes ? [["Requests", who.notes]] : [])].map(([k, v]) => (
            <div key={k} className="flex gap-4 px-4 py-2.5"><dt className="w-24 shrink-0 text-muted">{k}</dt><dd className="font-semibold break-words">{v}</dd></div>
          ))}
        </dl>
        <div className="flex gap-3">
          <Button variant="quiet" type="button" disabled={busy} onClick={() => setReview(false)}>Change</Button>
          <Button type="button" disabled={busy} onClick={confirm} className="flex-1">{busy ? "Booking…" : "Confirm reservation"}</Button>
        </div>
      </div>
    );
  }

  return (
    <form onSubmit={toReview} className="space-y-4 p-5">
      <div className="grid grid-cols-2 gap-3">
        <Field label={partyWord}>
          <select className={inputClass} value={party} onChange={(e) => { setParty(Number(e.target.value)); setSlot(null); }}>
            {Array.from({ length: maxParty }, (_, i) => i + 1).map((n) => <option key={n}>{n}</option>)}
          </select>
        </Field>
        <Field label="Date"><input type="date" required className={inputClass} value={date} min={today} max={maxDate} onChange={(e) => { setDate(e.target.value); setSlot(null); }} /></Field>
      </div>
      {services.length > 1 && (
        <Field label="Service">
          <select className={inputClass} value={service} onChange={(e) => { setService(e.target.value); setSlot(null); }}>{services.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select>
        </Field>
      )}
      <div>
        <p className="mb-1.5 text-sm font-semibold text-ink-soft">Time</p>
        <SlotPicker endpoint={`/api/public/${slug}/availability${service ? `?service=${service}` : ""}`} date={date} party={party} selected={slot?.start ?? null} onPick={setSlot} />
      </div>
      {alts.length > 0 && (
        <div className="rounded-xl bg-amber-soft p-3">
          <p className="mb-2 text-[15px] font-semibold text-amber">These times are free instead:</p>
          <div className="flex flex-wrap gap-2">
            {alts.map((a) => (
              <button key={a.start} type="button" className="rounded-lg bg-white px-3 py-2 text-[15px] font-semibold ring-1 ring-line hover:ring-brand"
                onClick={() => { setDate(a.date); setSlot({ start: a.start, time: a.time }); setAlts([]); setError(""); }}>
                {fmtDay(a.date)}, {a.time}
              </button>
            ))}
          </div>
        </div>
      )}
      <Field label="Name"><input required minLength={2} maxLength={80} autoComplete="name" className={inputClass} value={who.name} onChange={(e) => setWho({ ...who, name: e.target.value })} /></Field>
      <div className="grid gap-3 sm:grid-cols-2">
        <Field label="Email"><input type="email" maxLength={160} autoComplete="email" className={inputClass} value={who.email} onChange={(e) => setWho({ ...who, email: e.target.value })} /></Field>
        <Field label="Phone"><input type="tel" maxLength={30} autoComplete="tel" className={inputClass} value={who.phone} onChange={(e) => setWho({ ...who, phone: e.target.value })} /></Field>
      </div>
      <Field label="Special requests (optional)"><input maxLength={500} className={inputClass} value={who.notes} onChange={(e) => setWho({ ...who, notes: e.target.value })} /></Field>
      {/* Honeypot: hidden from people, tempting for bots. */}
      <div aria-hidden="true" className="absolute -left-[9999px] h-0 overflow-hidden">
        <label>Website<input tabIndex={-1} autoComplete="off" value={who.website} onChange={(e) => setWho({ ...who, website: e.target.value })} /></label>
      </div>
      <label className="flex items-start gap-2.5 text-[15px] text-ink-soft">
        <input type="checkbox" className="mt-0.5 size-5 accent-[var(--color-brand)]" checked={who.consent} onChange={(e) => setWho({ ...who, consent: e.target.checked })} />
        Email me the confirmation and a reminder for this reservation.
      </label>
      {error && <Notice tone="error">{error}</Notice>}
      <Button type="submit" className="w-full">Review reservation</Button>
    </form>
  );
}
